#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m,s;cin>>n>>m>>s;vector<vector<int>>g(n+1);for(int i=1,u,v;i<n;++i){cin>>u>>v;g[u].push_back(v);g[v].push_back(u);}int L=1;while((1<<L)<=n)++L;vector<vector<int>>up(L,vector<int>(n+1));vector<int>dep(n+1);queue<int>q;q.push(s);dep[s]=1;while(!q.empty()){int u=q.front();q.pop();for(int v:g[u])if(v!=up[0][u])up[0][v]=u,dep[v]=dep[u]+1,q.push(v);}for(int j=1;j<L;++j)for(int i=1;i<=n;++i)up[j][i]=up[j-1][up[j-1][i]];auto lca=[&](int a,int b){if(dep[a]<dep[b])swap(a,b);int d=dep[a]-dep[b];for(int j=0;j<L;++j)if(d>>j&1)a=up[j][a];if(a==b)return a;for(int j=L-1;j>=0;--j)if(up[j][a]!=up[j][b])a=up[j][a],b=up[j][b];return up[0][a];};while(m--){int a,b;cin>>a>>b;cout<<lca(a,b)<<'\n';}}
